import{apiFetch}from'./chat-api.js';
import{topics,record,status,question,parseAnswer,applyAnswer}from'./learning.js';
import{sectors,restoreJourney,energy,claim,travel}from'./journey.js';
const $=id=>document.getElementById(id),frame=$('universe');let journey;try{journey=restoreJourney(localStorage.getItem('math-voyage-v2'),localStorage.getItem('math-galaxy-v1'));}catch{journey=restoreJourney(null,null);}let selected=sectors[journey.current].ids[0],active=null,q=null,answered=false,helped=false,controller=null,history=[],apiReady=false,ready=false,warping=false,toastTimer;
const send=data=>frame.contentWindow?.postMessage(JSON.stringify(data),location.origin);
function persist(){try{localStorage.setItem('math-voyage-v2',JSON.stringify(journey));return true;}catch{$('storageWarning').textContent='浏览器无法保存进度；请保持本页打开。';return false;}}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function setSelected(id){if(!sectors[journey.current].ids.includes(id))return;selected=id;renderHUD();}
function renderHUD(){let sector=sectors[journey.current],t=topics.find(t=>t.id===selected);$('fuel').textContent=energy(journey);$('sectorCode').textContent=sector.code;$('sectorName').textContent=sector.name;$('sectorSub').textContent=sector.subtitle;let done=sector.ids.filter(id=>status(journey.learning,id)==='掌握').length;$('sectorProgress').textContent=`${done} / ${sector.ids.length} 星球已点亮`;$('missionTitle').textContent=t.name+' · 知识星球';$('missionText').textContent=status(journey.learning,t.id)==='掌握'?'这颗星球已经点亮。可以复习巩固，也可以启航探索新知识。':status(journey.learning,t.id)==='补强'?'这颗星球还有一处待修复。三三会陪你把困难拆成小步骤。':'独立完成 3 道不同题目，点亮星球，获得 3 点跃迁能量。';$('missionStars').textContent=Array.from({length:3},(_,i)=>i<record(journey.learning,t.id).wins.length?'★':'☆').join(' ');$('missionGo').textContent=status(journey.learning,t.id)==='掌握'?'降落 · 巩固知识 ↗':'降落 · 开始挑战 ↗';$('missionGo').disabled=warping;for(let b of $('planetPins').children){b.className='planet-pin'+(b.dataset.id===selected?' selected':'')+(status(journey.learning,b.dataset.id)==='掌握'?' master':'')+(status(journey.learning,b.dataset.id)==='补强'?' weak':'');}send({type:'mastered',ids:topics.filter(t=>status(journey.learning,t.id)==='掌握').map(t=>t.id)});}
function createPins(){ $('planetPins').replaceChildren();for(let id of sectors[journey.current].ids){let t=topics.find(t=>t.id===id),b=document.createElement('button');b.className='planet-pin';b.dataset.id=id;b.setAttribute('aria-label','选择星球：'+t.name);b.append(document.createTextNode(t.name));let small=document.createElement('small');small.textContent='↗';b.append(small);b.onclick=()=>setSelected(id);$('planetPins').append(b);}renderHUD();}
window.addEventListener('message',e=>{if(e.source!==frame.contentWindow||e.origin!==location.origin)return;let d;try{d=JSON.parse(e.data);}catch{return;}if(d.type==='loading'&&!ready)updateLoading(d);if(d.type==='ready'){ready=true;$('engineLoading').hidden=true;send({type:'sector',sector:journey.current});createPins();}if(d.type==='positions'){document.body.classList.toggle('is-flying',!!d.flying);for(let p of d.pins){let b=$('planetPins').querySelector(`[data-id="${p.id}"]`);if(!b)continue;b.hidden=!p.visible||p.x<.05||p.x>.95||p.y<.13||p.y>.84||warping;b.style.left=p.x*100+'%';b.style.top=p.y*100+'%';}$('velocity').textContent=d.speed;$('flightMode').textContent=d.flying?'自由驾驶模式':'星系观察模式';}if(d.type==='mode'){ $('flightHelp').hidden=!d.flying;$('mobileSteer').hidden=!d.flying||innerWidth>800;}if(d.type==='warp_done'){warping=false;$('warpOverlay').hidden=true;renderHUD();toast('已抵达 '+sectors[journey.current].name+'，新的知识星球等待探索。');} });
setTimeout(()=>{if(!ready){$('loadHint').textContent='加载时间较长，可以继续等待，或重试 / 打开轻量知识图谱。';$('retryEngine').hidden=false;}},30000);
$('retryEngine').onclick=()=>location.reload();
function showNavigation(){if(warping)return;$('sectorCards').replaceChildren();sectors.forEach((s,i)=>{let card=document.createElement('section');card.className='sector-card';card.style.setProperty('--planet',s.color);let orb=document.createElement('div');orb.className='mini-planet';card.append(orb);for(let [tag,text]of [['small',s.code],['h3',s.name],['p',s.subtitle],['p',`${s.ids.filter(id=>status(journey.learning,id)==='掌握').length} / ${s.ids.length} 星球已点亮`]]){let el=document.createElement(tag);el.textContent=text;card.append(el);}let b=document.createElement('button'),visited=journey.visited.includes(i);b.textContent=i===journey.current?'当前所在星系':visited?'免费返航 →':energy(journey)>=3?'跃迁 · 3 ✧ →':'需要 3 ✧ 能量';b.disabled=i===journey.current||(!visited&&energy(journey)<3)||!ready;b.onclick=()=>jump(i);card.append(b);$('sectorCards').append(card);});send({type:'pause',value:true});$('navigation').showModal();}
function jump(i){if(warping||!ready)return;let before=structuredClone(journey);if(!travel(journey,i)){toast('能量还不够，先点亮一颗知识星球吧。');return;}if(!persist()){journey=before;toast('存档失败，未消耗能量。请先恢复浏览器存储。');return;}warping=true;selected=sectors[i].ids[0];$('navigation').close();$('warpTarget').textContent=sectors[i].name+' · '+sectors[i].subtitle;$('warpOverlay').hidden=false;$('flightHelp').hidden=true;$('mobileSteer').hidden=true;createPins();send({type:'sector',sector:i,animate:true});setTimeout(()=>{if(warping){warping=false;$('warpOverlay').hidden=true;send({type:'sector',sector:journey.current});renderHUD();toast('航线已保存，已恢复到目标星系。');}},7000);}
$('galaxyMap').onclick=$('navigate').onclick=showNavigation;$('closeNavigation').onclick=()=>$('navigation').close();$('navigation').onclose=()=>send({type:'pause',value:false});$('overview').onclick=()=>{send({type:'overview'});$('flightHelp').hidden=true;$('mobileSteer').hidden=true;};$('pilot').onclick=()=>{send({type:'fly'});frame.contentWindow.focus();frame.contentDocument?.getElementById('canvas')?.focus();};$('focusPlanet').onclick=()=>send({type:'focus',id:selected});$('missionGo').onclick=()=>openLesson(selected);document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='m'&&!$('lesson').open&&!$('navigation').open)showNavigation();});document.querySelectorAll('#mobileSteer button').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();send({type:'controls',turn:Number(b.dataset.turn||0),thrust:Number(b.dataset.thrust||0)});};b.onpointerup=b.onpointercancel=()=>send({type:'controls',turn:0,thrust:0});});
function message(text,user=false){let b=document.createElement('div');b.className='bubble'+(user?' user':'');b.textContent=text;$('messages').append(b);$('messages').scrollTop=$('messages').scrollHeight;return b;}
function markHelp(){helped=true;let r=record(journey.learning,active.id);journey.learning.records[active.id]={...r,helpedKeys:[...new Set([...(r.helpedKeys||[]),q.key])]};persist();}
function cancel(){if(controller){let id=controller.requestId;controller.abort();controller=null;apiFetch('/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId:id}),keepalive:true}).catch(()=>{});}$('send').textContent='↑';$('send').setAttribute('aria-label','发送消息');}
function openLesson(id){cancel();active=topics.find(t=>t.id===id);history=[];$('messages').replaceChildren();message(`欢迎降落「${active.name}」！每个独立的小发现，都在为飞船补充能量。`);$('topicGroup').textContent=sectors[journey.current].name+' / '+active.group;$('topicName').textContent=active.name;$('lessonText').textContent=active.lesson;newQuestion();send({type:'pause',value:true});$('lesson').showModal();$('answer').focus();}
function newQuestion(){cancel();let r=record(journey.learning,active.id);q=question(active.id,r.attempts);helped=!!r.helpedKeys?.includes(q.key);answered=false;$('question').textContent=q.q;$('questionNumber').textContent=`星球挑战 · 第 ${r.attempts+1} 次探索`;$('milestones').textContent=Array.from({length:3},(_,i)=>i<r.wins.length?'★':'☆').join(' ');$('feedback').textContent='';$('feedback').className='';$('answer').value='';$('answer').disabled=false;$('check').disabled=false;$('next').hidden=true;$('skip').hidden=false;$('hint').disabled=false;$('answer').focus();}
$('answerForm').onsubmit=e=>{e.preventDefault();if(answered)return;let n=parseAnswer($('answer').value);if(!Number.isFinite(n)){$('feedback').textContent='输入数字、小数或分数，例如 1/2。';return;}let correct=Math.abs(n-q.ans)<1e-8;applyAnswer(journey.learning,active.id,q,correct,helped);let awarded=claim(journey,active.id);persist();answered=true;$('answer').disabled=$('check').disabled=true;$('next').hidden=false;$('skip').hidden=true;$('feedback').className=correct?'good':'';$('feedback').textContent=(awarded?'星球点亮！已获得 3 ✧ 跃迁能量。回到星系后点击「星际跃迁」，去探索新的知识！':correct?(helped?'答对了！有帮助的练习不计入独立通关，下题试试看。':'答对了！新的星光正在汇聚。'):'还差一点，我们一起修复这个小缺口：')+' '+q.explain;$('milestones').textContent=Array.from({length:3},(_,i)=>i<record(journey.learning,active.id).wins.length?'★':'☆').join(' ');if(awarded)$('buddyText').textContent='跃迁引擎已充能！点击「星际跃迁」，出发去新的星系。';renderHUD();};
$('hint').onclick=()=>{markHelp();message(q.hint);$('feedback').textContent='三三已给出提示，这题作为有帮助的练习。';};$('skip').onclick=()=>{if(answered)return;applyAnswer(journey.learning,active.id,q,false,true);persist();answered=true;$('answer').disabled=$('check').disabled=true;$('next').hidden=false;$('skip').hidden=true;let pre=active.pre.map(id=>topics.find(t=>t.id===id).name);$('feedback').textContent=pre.length?'已标记需补强。建议先检查：'+pre.join('、')+'。可以从星系导航免费返回已到访的星系。':'没关系，先看看提示，再用下一题练一练。';renderHUD();};$('next').onclick=newQuestion;$('close').onclick=()=>$('lesson').close();$('lesson').onclose=()=>{cancel();send({type:'pause',value:false});renderHUD();};
async function ask(text){if(!text.trim()||!active)return;if(controller){cancel();return;}markHelp();message(text,true);$('chatInput').value='';if(!apiReady){message('目前是离线提示模式。'+(/简单|理解|知识/.test(text)?active.lesson:q.hint));return;}let c=new AbortController();c.requestId=crypto.randomUUID();controller=c;let id=active.id,b=message('三三正在接收来自 AgentCore 的回答…');$('send').textContent='■';$('send').setAttribute('aria-label','停止回答');let timer=setTimeout(()=>{if(controller===c)cancel();},165000);try{let res=await apiFetch('/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId:c.requestId,topicId:id,questionIndex:record(journey.learning,id).attempts-(answered?1:0),message:text,history:history.slice(-8)}),signal:c.signal});let d=await res.json();if(!res.ok)throw Error(d.error||'问答服务暂不可用');if(active.id!==id)return;b.textContent=d.reply;history.push({role:'user',content:text},{role:'assistant',content:d.reply});}catch(e){b.textContent=c.signal.aborted?'回答已停止或超时。你可以重新发送问题。':(e.message||'问答服务暂时没有接通，请稍后重试。');}finally{clearTimeout(timer);if(controller===c){controller=null;$('send').textContent='↑';$('send').setAttribute('aria-label','发送消息');}}}
$('chatForm').onsubmit=e=>{e.preventDefault();controller?cancel():ask($('chatInput').value);};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>ask(b.dataset.prompt));apiFetch('/health').then(r=>r.ok?r.json():null).then(d=>{apiReady=d?.agentcore===true;$('chatMode').textContent=apiReady?'三三在线 · AWS AgentCore':'离线提示模式';}).catch(()=>$('chatMode').textContent='离线提示模式');
createPins();persist();

// Start Godot only after its message listener and UI are installed.
frame.src=frame.dataset.src;

function updateLoading(d){
  const bar=$('loadProgress'),detail=$('loadDetail');
  if(d.phase==='download'&&Number.isFinite(d.loaded)&&d.total>0){
    const percent=Math.min(100,Math.floor(d.loaded/d.total*100));
    bar.value=percent;$('loadStage').textContent='正在下载星际引擎';
    detail.textContent=`${percent}% · ${(d.loaded/1048576).toFixed(1)} / ${(d.total/1048576).toFixed(1)} MB`;
  }else if(d.phase==='start'){
    bar.removeAttribute('value');$('loadStage').textContent='资源下载完成，正在启动宇宙';detail.textContent='正在解压、编译并准备星系画面…';
  }else if(d.phase==='error'){
    bar.removeAttribute('value');$('loadStage').textContent='暂时没能展开宇宙';detail.textContent=d.message||'启动失败，请重试。';$('retryEngine').hidden=false;
  }else if(d.phase==='prepare'){$('loadStage').textContent='正在准备星际引擎';}
}
